const errorData = $input.first().json;
const execution = errorData.execution || {};
const error = execution.error || {};
const lastNode = execution.lastNodeExecuted || 'unknown';
const errorMsg = (error.message || 'Unknown error').replace(/'/g, "''").substring(0, 500);
const errorStack = (error.stack || '').replace(/'/g, "''").substring(0, 500);

// Try to extract runId from the workflow data
let runId = null;
try {
  const nodes = execution.workflowData?.nodes || [];
  const setVarsNode = nodes.find(n => n.name === 'Set Variables');
  if (setVarsNode?.parameters?.assignments?.assignments) {
    const runIdAssignment = setVarsNode.parameters.assignments.assignments.find(a => a.name === 'runId');
    if (runIdAssignment) runId = runIdAssignment.value;
  }
} catch(e) {}

// Also try from the execution data directly
if (!runId) {
  try {
    const resultData = execution.resultData?.runData?.['Set Variables'];
    if (resultData?.[0]?.data?.main?.[0]?.[0]?.json?.runId) {
      runId = resultData[0].data.main[0][0].json.runId;
    }
  } catch(e) {}
}

return [{ json: { runId, lastNode, errorMsg, errorStack } }];
